// Owned by the integrations subsystem (architecture Amendment 9, A9.1 and A9.2). Recipes are data
// (reads, words, query templates), never code or secrets; check results are per integration and read.
// Migration: generated by the lead (shared file request, recipes build r1); export it from index.ts.
import { index, integer, primaryKey, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { integrations } from "./integrations";

export const recipes = sqliteTable(
  "recipe",
  {
    id: text("id").primaryKey(), // the recipe id ("grafana/1860"); built-in ids hold only a status override
    // The validated Recipe file; null for a built-in recipe (its reads ship in the repo).
    record: text("record", { mode: "json" }).$type<Record<string, unknown> | null>(),
    source: text("source", { enum: ["builtin", "file", "url", "grafana", "spec"] }).notNull(),
    status: text("status", { enum: ["draft", "active"] }).notNull(),
    // Why a stored record no longer validates (listed with the problem; the rest still load).
    problem: text("problem"),
    // Grafana imports: the panels that could not become reads, with the reason.
    skipped: text("skipped", { mode: "json" }).$type<{ title: string; reason: string }[]>().notNull().default([]),
    // A spec recipe made from this integration (A9.3); it applies here even before a title match.
    originIntegrationId: text("origin_integration_id"),
    createdById: text("created_by_id"),
    importedAt: integer("imported_at", { mode: "timestamp_ms" }).notNull(),
    updatedAt: integer("updated_at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [index("recipe_source_idx").on(t.source)],
);

export const readChecks = sqliteTable(
  "read_check",
  {
    integrationId: text("integration_id").notNull().references(() => integrations.id, { onDelete: "cascade" }),
    endpointId: text("endpoint_id").notNull(),
    status: text("status", { enum: ["ok", "empty", "failed", "odd"] }).notNull(),
    reason: text("reason"),
    // The status before this one, so a read that used to work and now fails can be told apart.
    previous: text("previous", { enum: ["ok", "empty", "failed", "odd"] }),
    at: integer("at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.integrationId, t.endpointId] })],
);
